<script setup>
import {ref,watch} from 'vue'
import Icon from '../Icon.vue'
import {request} from './client'
import {previewMode} from '../preview/mode'
const props=defineProps({account:Object,gatewayReady:Boolean}),emit=defineEmits(['refresh'])
const method=ref('Bank transfer'),email=ref(''),auto=ref(false),consent=ref(false),busy=ref(false),message=ref(''),error=ref('')
watch(()=>props.account,a=>{method.value=a.payment_method||'Bank transfer';email.value=a.billing_email;auto.value=!!a.auto_pay;consent.value=!!a.auto_pay},{immediate:true})
async function act(name,args={}){busy.value=true;error.value='';message.value='';try{const r=await request('commercial',name,{account:props.account.name,...args});if(r.redirect_url){const url=new URL(r.redirect_url);if(url.protocol!=='https:'||!['payments.lk','checkout.payments.lk'].includes(url.hostname))throw Error('Payment page could not be verified');location.assign(url.href);return}message.value=r.message||'Billing preferences updated.';emit('refresh')}catch(e){error.value=e.message}finally{busy.value=false}}
function save(){return act('save_billing_preferences',{payment_method:method.value,billing_email:email.value,auto_pay:method.value==='Card'&&auto.value,consent:consent.value})}
</script>
<template><section class="payment-settings"><div class="settings-title"><div><span class="eyebrow">PAYMENT PREFERENCES</span><h2>Your billing, your way.</h2></div><Icon name="CreditCard" :size="25"/></div>
<div class="method-options"><button :aria-pressed="method==='Card'" @click="method='Card'" type="button"><Icon name="CreditCard" :size="19"/><span>Bank card<small>Automatic monthly billing</small></span><span>{{method==='Card'?'●':'○'}}</span></button><button :aria-pressed="method==='Bank transfer'" @click="method='Bank transfer'" type="button"><Icon name="Building2" :size="19"/><span>Bank transfer<small>Pay invoice & upload proof</small></span><span>{{method==='Bank transfer'?'●':'○'}}</span></button></div>
<div v-if="method==='Card'" class="card-method"><div class="masked-card"><span>{{account.card?.brand||'YOUR PAYMENT CARD'}}</span><strong>•••• &nbsp; •••• &nbsp; •••• &nbsp; {{account.card?.last4||'— — — —'}}</strong><small>{{account.card?'Expires '+account.card.expiry:'Add your card on the secure payment page'}}{{previewMode?' · Demo':''}}</small></div><div><button class="button subtle" :disabled="busy||(!previewMode&&!gatewayReady)" @click="act('card_setup')">{{account.card?'Update card':'Add card'}}{{previewMode?' · demo':''}}</button><button v-if="account.card" class="text-button" :disabled="busy" @click="act('remove_card')">Remove card</button></div><p v-if="!previewMode&&!gatewayReady" class="field-help">Card billing will be available after SISU completes merchant setup.</p><label class="check-row"><input type="checkbox" v-model="auto" :disabled="!account.card">Automatically pay my monthly SISU invoice</label><label v-if="auto&&!account.auto_pay" class="check-row consent"><input type="checkbox" v-model="consent">I authorise SISU to charge the monthly package fee plus the active enrolments shown on each invoice. I can turn this off or switch to bank transfer before the next charge.</label><p class="field-help">Your invoice is created at the end of each cycle. A receipt follows only after confirmed payment. SISU never stores your full card number or security code.</p></div>
<div v-else class="transfer-note"><Icon name="FileText" :size="23"/><div><strong>Pay from your bank. Keep the invoice reference.</strong><p>{{account.bank_instructions||'Open an invoice for SISU’s bank details and upload your transfer receipt. Payment is marked paid after verification.'}}</p><p>Choosing this option turns off future automatic card charges.</p></div></div>
<form @submit.prevent="save"><label class="email-field">Invoice & receipt email<input v-model="email" type="email" required maxlength="140" autocomplete="email"></label><div class="save-row"><span v-if="previewMode">Presentation mode · no charges or emails</span><button class="button primary" :disabled="busy">Save billing preferences</button></div></form><p v-if="message" role="status" class="settings-message">{{message}}</p><p v-if="error" role="alert" class="error">{{error}}</p>
</section></template>
<style scoped>
.payment-settings{padding:28px;background:var(--student-card,#fff);border:1px solid var(--student-border,#e8e0ef);border-radius:22px}.settings-title{display:flex;justify-content:space-between;gap:16px;align-items:center}.settings-title h2{font-size:23px;margin:9px 0 24px}.method-options{display:grid;grid-template-columns:1fr 1fr;gap:12px}.method-options>button{display:flex;align-items:center;gap:12px;text-align:left;border:1px solid #e5deef;background:var(--student-card,#fff);color:inherit;border-radius:12px;padding:16px}.method-options>button[aria-pressed=true]{border-color:#7040a1;background:#f5f0fb;color:#512781}.method-options small{display:block;font-size:10px;margin-top:5px}.method-options>button>span:last-child{margin-left:auto}.card-method{margin-top:20px;display:grid;gap:16px}.masked-card{max-width:390px;display:grid;gap:22px;background:linear-gradient(120deg,#2d164b,#7040a1);color:white;padding:24px;border-radius:18px;box-shadow:0 12px 25px #4f24721a}.masked-card>span{font-size:11px;letter-spacing:2px}.masked-card strong{font-size:19px;letter-spacing:1px}.masked-card small{color:#e1d2f0;font-size:11px}.check-row{display:flex;gap:10px;align-items:flex-start;font-size:13px;line-height:1.7}.check-row input{width:17px;height:17px;flex-shrink:0;margin-top:3px;accent-color:#613292}.consent{background:#f8f5fc;padding:14px;border-radius:10px}.email-field{display:grid;gap:9px;font-size:12px;margin-top:22px}.email-field input{padding:13px;border:1px solid #e1d9e9;border-radius:10px;background:var(--student-card,#fff);color:inherit}.transfer-note{display:flex;gap:14px;padding:22px 0;font-size:13px;line-height:1.7}.transfer-note svg{flex-shrink:0;color:#7040a1}.transfer-note p{margin:8px 0;color:var(--student-muted,#786d83)}.save-row{display:flex;gap:14px;align-items:center;justify-content:space-between;margin-top:18px}.save-row>span{font-size:10px;color:var(--student-muted,#786d83)}.settings-message{font-size:13px;margin-top:12px;color:#42795c}.text-button{margin-left:15px}.field-help{font-size:11px;line-height:1.7}@media(max-width:600px){.method-options{grid-template-columns:1fr}.payment-settings{padding:20px}.save-row{align-items:flex-start;flex-direction:column}}
</style>
